{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Ofloxacin showed absolute oral bioavailability >95% in healthy volunteers after a 200 mg oral dose compared with IV.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C68"],
      "claim": "Trovafloxacin had an absolute oral bioavailability of 88% after a single 200 mg oral dose in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Sildenafil had a mean absolute oral bioavailability of 41% (range 25-63%) in human subjects.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Each supplied evidence molecule has at least one strong human numeric oral bioavailability record above the 20% threshold; direct absolute measurements range from about 30% to near 100%, and high assay-transfer scores support a high F>=20 prediction.",
  "evidence_gaps": [
    "Some records are not explicitly absolute bioavailability, though their numeric values are still above 20%.",
    "Molecule 8's card set mixes emtricitabine records with didanosine records; the inconsistent didanosine cards were discounted.",
    "Pediatric didanosine records report F as low as 13%, while adult absolute values are 30-54%; population-specific variability remains unresolved."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

